((document) => {

  // Selectors.
  const layoutContainerSelector = '.microsoft-template-layout-container';
  const uhfSelector = '#uhfSkipToMain';
  const acomSelector = '.azure-skip-nav';

  // Content IDs.
  const defaultContentId = 'mainContent';
  const defaultAcomContentId = 'main';

  /**
   * Applies the UHF layout container ID based on the skip link href.
   */
  const applyUhfLayoutContainerId = () => {
    // Get the skip link element from the DOM (Azure or standard UHF).
    let uhfSkipToMain = document.querySelector(uhfSelector);
    let acomHeaderSkipToMain = document.querySelector(acomSelector);
    let targetId = uhfSkipToMain ? defaultContentId : defaultAcomContentId;

    // Set the ID of the layout container based on the skip link href.
    if (uhfSkipToMain?.dataset?.href) {
      targetId = uhfSkipToMain.dataset.href.replace("#", "") || targetId;
    } else if (acomHeaderSkipToMain?.getAttribute("href")) {
      targetId = acomHeaderSkipToMain.getAttribute("href").replace("#", "") || targetId;
    }
    document.querySelector(layoutContainerSelector)?.setAttribute("id", targetId);
  };

  // Apply the layout container ID on page load.
  document.addEventListener('DOMContentLoaded', applyUhfLayoutContainerId);
})(document);
